using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using System.Security.Claims;
using TuTuc.Models;
using TuTuc.Services;
namespace TuTuc.Controllers;
public class AccountController(AccountManager accounts,IConfiguration config):Controller {
 int Me=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 public IActionResult Login(string? returnUrl){ViewBag.DemoEnabled=config.GetValue<bool>("Demo:Enabled");return View(new LoginInput{ReturnUrl=returnUrl});}
 [HttpPost]public async Task<IActionResult> Login(LoginInput input){ViewBag.DemoEnabled=config.GetValue<bool>("Demo:Enabled");if(!ModelState.IsValid)return View(input);var user=await accounts.Authenticate(input.Email,input.Password);if(user is null){ModelState.AddModelError("","Thông tin đăng nhập không đúng hoặc tài khoản không còn hoạt động.");return View(input);}await SignIn(user);return GoHome(user,input.ReturnUrl);}
 [HttpPost]public async Task<IActionResult> LoginDemo(string role,string? returnUrl){if(!config.GetValue<bool>("Demo:Enabled"))return NotFound();var email=role switch{"Traveler"=>"khach@demo.vn","Provider"=>"ncc@demo.vn","Admin"=>"admin@demo.vn",_=>null};if(email is null)return BadRequest();var user=await accounts.Authenticate(email,"Demo12345");if(user is null){TempData["Message"]="Tài khoản demo chưa sẵn sàng.";return RedirectToAction(nameof(Login));}await SignIn(user);return GoHome(user,returnUrl);}
 public IActionResult Denied()=>View();
 public IActionResult Register()=>User.Identity?.IsAuthenticated==true?RedirectToAction(nameof(Profile)):View(new RegisterInput());
 [HttpPost,RequestSizeLimit(28000000)]public async Task<IActionResult> Register(RegisterInput input){if(User.Identity?.IsAuthenticated==true)return RedirectToAction(nameof(Profile));if(!ModelState.IsValid)return View(input);var result=await accounts.Register(input);if(result.User is null){ModelState.AddModelError("",result.Error);return View(input);}TempData["Message"]=input.Role=="Provider"?"Đăng ký thành công. Hồ sơ đang chờ xác minh; hãy đăng nhập để theo dõi và bổ sung khi được yêu cầu.":"Đăng ký thành công. Hãy đăng nhập để bắt đầu hành trình.";return RedirectToAction(nameof(Login));}
 [Authorize]public async Task<IActionResult> Profile(){var vm=await accounts.Profile(Me);return vm is null?NotFound():View(vm);}
 [Authorize,HttpPost,RequestSizeLimit(6000000)]public async Task<IActionResult> UpdateProfile(ProfileInput input){var error=ModelState.IsValid?await accounts.UpdateProfile(Me,input):"Thông tin hồ sơ chưa hợp lệ. Kiểm tra các trường được đánh dấu.";if(error.Length>0){ModelState.AddModelError("",error);var vm=await accounts.Profile(Me);if(vm is null)return NotFound();vm.Input=input;return View("Profile",vm);}await SignIn((await accounts.Find(Me))!);TempData["Message"]="Đã lưu hồ sơ. Vai trò và trạng thái xác minh được giữ nguyên.";return RedirectToAction(nameof(Profile));}
 [Authorize,HttpPost]public async Task<IActionResult> ChangePassword(PasswordInput input){if(!ModelState.IsValid){TempData["Message"]=string.Join(" ",ModelState.Values.SelectMany(x=>x.Errors).Select(x=>x.ErrorMessage));return RedirectToAction(nameof(Profile));}var error=await accounts.ChangePassword(Me,input);if(error.Length>0){TempData["Message"]=error;return RedirectToAction(nameof(Profile));}await SignIn((await accounts.Find(Me))!);TempData["Message"]="Đã đổi mật khẩu. Các phiên đăng nhập cũ đã hết hiệu lực.";return RedirectToAction(nameof(Profile));}
 [Authorize(Roles="Traveler,Provider"),HttpGet]public IActionResult Deactivate()=>View(new DeactivationPage());
 [Authorize(Roles="Traveler,Provider"),HttpPost]public async Task<IActionResult> Reauthenticate(string password){var result=await accounts.PreviewDeactivation(Me,password);if(result.Error.Length>0){ModelState.AddModelError("",result.Error);return View("Deactivate",new DeactivationPage());}return View("Deactivate",result.Page);}
 [Authorize(Roles="Traveler,Provider"),HttpPost]public async Task<IActionResult> Deactivate(string token,string version){var error=await accounts.Deactivate(Me,token,version);if(error.Length>0){ModelState.AddModelError("",error);return View(new DeactivationPage());}await HttpContext.SignOutAsync();TempData["Message"]="Tài khoản đã ngừng sử dụng. Lịch sử nghiệp vụ đã lưu được giữ lại.";return RedirectToAction("Index","Home");}
 [HttpPost]public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return RedirectToAction("Index","Home");}
 async Task SignIn(Account u)=>await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Name),new Claim(ClaimTypes.Role,u.Role),new Claim("session_stamp",u.SessionStamp),new Claim("signed_in_at",DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString())},CookieAuthenticationDefaults.AuthenticationScheme)),new AuthenticationProperties{IsPersistent=false});
 IActionResult GoHome(Account u,string? returnUrl){if(!string.IsNullOrWhiteSpace(returnUrl)&&Url.IsLocalUrl(returnUrl))return LocalRedirect(returnUrl);return u.Role switch{"Admin"=>RedirectToAction("Index","Admin"),"Provider"=>RedirectToAction("Index","Provider"),_=>RedirectToAction("Index","Journey")};}
}
